catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
   var record =    g_form.getValue('number');
   var ga = new GlideAjax('UpdatePriorityConfigurationRule');
   ga.addParam('sysparm_name','UpdateConfigurationRule');
   ga.addParam('sysparm_checklist',record);
   ga.getXMLAnswer(updateRule);

   }
   function updateRule(response){
	var client = JSON.parse(response);
    g_form.setValue('enabled', client.enabled);
	g_form.setValue('u_target_app',client.u_target_app);
	g_form.setValue('field_from_task',client.field_from_task);
	g_form.setValue('entity',client.entity);
	g_form.setValue('from_table',client.from_table);
	g_form.setValue('expected_value',client.expected_value);
	g_form.setValue('expected_display',client.expected_display);
	g_form.setValue('points',client.points);
	g_form.setValue('u_fff',client.u_fff);
   }
